#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricApparentEnergy::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricApparentEnergy::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricApparentEnergyUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricApparentEnergy::from_base(0.0).auto_unit().unit,
        ElectricApparentEnergyUnit::VoltampereHour
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "VAh".parse::<ElectricApparentEnergyUnit>(),
        Ok(ElectricApparentEnergyUnit::VoltampereHour)
    );
    assert_eq!(
        format!("2.5 {}", "VAh").parse::<ElectricApparentEnergy>(),
        Ok(ElectricApparentEnergy::new(
            2.5,
            ElectricApparentEnergyUnit::VoltampereHour
        ))
    );
    assert_eq!(
        "kVAh".parse::<ElectricApparentEnergyUnit>(),
        Ok(ElectricApparentEnergyUnit::KilovoltampereHour)
    );
    assert_eq!(
        format!("2.5 {}", "kVAh").parse::<ElectricApparentEnergy>(),
        Ok(ElectricApparentEnergy::new(
            2.5,
            ElectricApparentEnergyUnit::KilovoltampereHour
        ))
    );
    assert_eq!(
        "MVAh".parse::<ElectricApparentEnergyUnit>(),
        Ok(ElectricApparentEnergyUnit::MegavoltampereHour)
    );
    assert_eq!(
        format!("2.5 {}", "MVAh").parse::<ElectricApparentEnergy>(),
        Ok(ElectricApparentEnergy::new(
            2.5,
            ElectricApparentEnergyUnit::MegavoltampereHour
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricApparentEnergy>(),
        Err(ParseError::UnknownUnit)
    );
}

